{"cards": [{"node_code": "N_86666ccf4dff1631", "definition": "研究体内水、电解质及酸碱平衡失调的发生机制、临床表现及代偿调节规律的病理生理过程，涵盖脱水、水肿、高/低钾血症及酸中毒等。", "boundary": "本节点聚焦于内环境稳态失衡，特别是体液容量、渗透压及pH值的异常。与缺氧区分，本节点关注化学环境而非氧供；与休克区分，本节点侧重代谢紊乱本身，而非循环衰竭。", "includes": ["水与钠代谢紊乱（如脱水、水肿）", "钾、钙、镁等电解质代谢异常", "酸碱平衡紊乱（如代谢性酸中毒、呼吸性碱中毒）"], "excludes": ["单纯的血容量不足导致的循环衰竭（归入休克）", "气体交换障碍导致的低氧血症（归入缺氧）"], "sibling_distinctions": [{"other_code": "N_b38c786e27688cd8", "rule": "本节点关注体液化学环境（水、盐、pH）；缺氧关注氧气供应与利用。"}, {"other_code": "N_d566ca8a3f1870ed", "rule": "本节点侧重内环境成分失衡；休克侧重有效循环血量不足及微循环障碍。"}], "cross_boundary_rule": ""}, {"node_code": "N_b38c786e27688cd8", "definition": "研究机体组织供氧不足或耗氧增加导致细胞能量代谢障碍的病理过程，涵盖低张性、血液性、循环性及组织性缺氧的发生机制与代偿反应。", "boundary": "本节点聚焦于氧的运输、交换及利用障碍。与水电解质紊乱区分，本节点核心是氧分压与血红蛋白功能；与休克区分，休克是循环衰竭，缺氧是结果或伴随状态，但本节点独立研究缺氧本身的机制。", "includes": ["低张性缺氧（如高原、肺部疾病）", "血液性缺氧（如贫血、CO中毒）", "循环性缺氧与组织性缺氧（如氰化物中毒）"], "excludes": ["单纯的水电解质失衡（归入水、电解质与酸碱平衡紊乱）", "微循环衰竭导致的全身性循环障碍（归入休克）"], "sibling_distinctions": [{"other_code": "N_86666ccf4dff1631", "rule": "本节点关注氧的供需平衡；水、电解质与酸碱平衡紊乱关注体液化学成分。"}, {"other_code": "N_d566ca8a3f1870ed", "rule": "本节点研究缺氧机制；休克研究循环衰竭，休克常导致循环性缺氧，但概念不同。"}], "cross_boundary_rule": ""}, {"node_code": "N_86b070553496a5c2", "definition": "研究机体在受到各种有害刺激时产生的非特异性全身性适应反应，涵盖应激原、应激反应（神经-内分泌-免疫网络）及应激相关疾病的发生机制。", "boundary": "本节点聚焦于机体对压力的整体适应性反应，特别是HPA轴和交感-肾上腺髓质系统的激活。与发热区分，发热是炎症或感染的具体表现，应激是更广泛的非特异性反应；与休克区分，应激是代偿过程，休克是失代偿的循环衰竭。", "includes": ["应激原的分类与识别", "应激反应的神经内分泌机制（如皮质醇、儿茶酚胺）", "应激对机体功能的影响及应激相关疾病（如应激性溃疡）"], "excludes": ["特异性免疫反应（归入免疫学）", "单纯的循环衰竭状态（归入休克）"], "sibling_distinctions": [{"other_code": "N_d7061bd92a2fda1a", "rule": "本节点关注非特异性适应反应；发热是炎症介质引起的体温调定点上移，常作为应激或感染的表现。"}, {"other_code": "N_d566ca8a3f1870ed", "rule": "本节点侧重机体的代偿性适应；休克侧重循环系统的失代偿与衰竭。"}], "cross_boundary_rule": ""}]}
